@startuml

class Bus {
  + licensePlate : string
}

class Driver {
  + name : string
  + id : int
  + onSickLeave : boolean
}

class Route {
  + routeNumber : int
}

class Shift {
  + shiftType : string
}

class Assignment {
  + date : date
  + bus : Bus
  + driver : Driver
  + shift : Shift
}

class Overview {
  + routeNumber : int
  + assignedBuses : Bus[]
  + enteredShifts : Shift[]
  + assignedDrivers : Driver[]
}

Bus "1" -- "*" Assignment
Driver "1" -- "*" Assignment
Route "1" -- "*" Assignment
Assignment "0..1" -- "1" Overview

@enduml

